const inputItem = $input.first();
const input = inputItem.json;
const binaryData = inputItem.binary; 

let subject = "Strategic Operational Scaling: Agentic AI Systems";
let body = "No content generated";
let recipientEmail = "client@example.com";
let hasAttachment = false;
let attachmentName = "";

if (binaryData && (binaryData.attachment || binaryData.data)) {
  hasAttachment = true;
  const fileObj = binaryData.attachment || binaryData.data;
  attachmentName = fileObj.fileName || "CV_Attachment.pdf";
}

function extractData(obj) {
  if (!obj) return;
  if (obj.subject || obj.email_subject) subject = obj.subject || obj.email_subject;
  if (obj.body || obj.email_body || obj.text) body = obj.body || obj.email_body || obj.text;
  if (obj.recipient_email || obj.email || obj.to) recipientEmail = obj.recipient_email || obj.email || obj.to;
}

extractData(input);

if (input.output) {
  if (typeof input.output === 'object') {
    extractData(input.output);
  } else if (typeof input.output === 'string') {
    try {
      const parsed = JSON.parse(input.output);
      extractData(parsed);
    } catch (e) {
      body = input.output;
    }
  }
}

if (!recipientEmail || String(recipientEmail).trim() === "") {
  recipientEmail = "client@example.com";
}

// 1. جلب رابط الاستئناف
let resumeUrl = $execution.resumeUrl;

// 2. معالجة وضع الاختبار اليدوي
if (!resumeUrl || String(resumeUrl).includes('{resumeUrl}')) {
  resumeUrl = "https://example.com/test-approval"; 
}

// 3. بناء الرابط بأسلوب JavaScript الصحيح
const separator = resumeUrl.includes('?') ? '&' : '?';
const approveUrl = `\({resumeUrl}\){separator}decision=approve`;
const rejectUrl  = `\({resumeUrl}\){separator}decision=reject`;

// 4. إرجاع المخرجات مع الحفاظ على ملف الـ Binary إن وجد
return [{
  json: {
    recipient_email: recipientEmail,
    email_subject: subject,
    email_body: body,
    has_attachment: hasAttachment,
    attachment_name: attachmentName,
    approve_url: approveUrl,
    reject_url: rejectUrl
  },
  binary: binaryData
}];

